"""Publish the approved MagicPath editorial design as independent static public pages.
Content lives in docs/website/editorial; application documents remain independently built.
"""
from pathlib import Path
from html import escape
import re
ROOT=Path(__file__).resolve().parents[1]; D=ROOT/'docs'; CONTENT=D/'website/editorial'
STORE='https://apps.apple.com/au/app/fieldops-by-drillops/id6797079076'
PRODUCTS={
'FieldOps':('fieldops.html','AVAILABLE NOW · iPHONE + iPAD','Your data.<br>Your ground.<br>Your FieldOps.','Take your GIS into the field. Bring your own maps, explore terrain and capture what matters — on your device.','fieldops-terrain.png'),
'FieldMaps':('fieldmaps.html','COMING SOON · A FIRST LOOK','A new view.<br>A shared<br>perspective.','Meet FieldMaps. A clearer place to bring your spatial files together and put your project on the map.','fieldmaps-web.png'),
'EOS':('drillops.html','DRILLOPS FOR BUSINESS','See the shift.<br>Understand<br>the operation.','Bring drilling activity reports and production information into a clearer operational picture.','activities-dar.png'),
'Account':('accounting.html','DRILLOPS FOR BUSINESS','A clearer view<br>of the numbers.','Bring the financial detail of your operation into a focused workspace for review.','account-ledger.png'),
'Project':('project-management.html','DRILLOPS FOR BUSINESS','Keep the whole<br>project in view.','A focused workspace for the project information your team needs to keep work moving.','project-dashboard.png')}
APPS={'EOS':'eos.html','Account':'account.html','Project':'project.html'}
def brand():return '<a class="dd-brand" href="./index.html" aria-label="DrillOps home"><span class="dd-mark" aria-hidden="true">↗</span>DrillOps<span class="dd-dot">.</span></a>'
def header(current):
 links=''.join(f'<a href="./{p[0]}"'+(' aria-current="page" class="active"' if n==current else '')+f'>{n}'+('<sup>SOON</sup>' if n=='FieldMaps' else '')+'</a>' for n,p in PRODUCTS.items())
 return f'<a class="skip" href="#main">Skip to content</a><header class="dd-header">{brand()}<button class="dd-menu" type="button" aria-controls="product-nav" aria-expanded="false">Menu +</button><nav id="product-nav" aria-label="Products">{links}</nav><a class="dd-contact" href="mailto:admin@drillops.com.au">Let’s talk ↗</a></header>'
def footer():return f'<footer>{brand()}<p>From field to office.</p><div class="dd-footerlinks"><a href="./support.html">Support</a><a href="./privacy.html">Privacy</a><a href="./fieldops-privacy.html">FieldOps privacy</a><a href="./eos.html">Sign in ↗</a><span>© 2026 DrillOps</span></div></footer>'
def img(name,alt,attrs=''):
 return f'<img src="./assets/products/{name}" alt="{escape(alt)}" {attrs}>'
def page(path,title,desc,body,current='',home=False):
 (D/path).write_text(f'''<!doctype html>
<!-- Generated by scripts/build_editorial_site.py; edit docs/website/editorial for detailed content. -->
<html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="https://www.drillops.com.au/{'' if home else path}"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><meta name="theme-color" content="#fafaf6"><link rel="icon" href="./favicon.svg"><link rel="stylesheet" href="./editorial.css?v=20261109-1"><script defer src="./editorial.js?v=20261109-1"></script>{'<script src="./public-entry.js"></script>' if home else ''}</head><body class="drill-design">{header(current)}<main id="main">{body}</main>{footer()}</body></html>\n''')
def build_home():
 cards=''.join(f'<a href="./{PRODUCTS[n][0]}"><span>0{i+3} / DRILLOPS</span><h3>{n} <b>↗</b></h3><p>{PRODUCTS[n][3]}</p></a>' for i,n in enumerate(APPS))
 body=f'''<section class="dd-homehero"><div class="dd-kicker"><i></i> SOFTWARE FOR THE FIELD. CLARITY FOR THE BUSINESS.</div><div class="dd-headrow"><h1>Good work starts<br>with a <span>clearer view.</span></h1><div class="dd-intro"><p>From the ground beneath your feet to the detail behind your operation. Discover tools that bring the work into focus.</p><a class="dd-primary" href="./fieldops.html">Explore FieldOps <b>↗</b></a></div></div><div class="dd-rule"><span>THE DRILLOPS COLLECTION</span><span>FIELD → OFFICE</span></div></section>
<section class="dd-feature"><div class="dd-featurecopy"><span class="dd-pill">AVAILABLE NOW</span><p class="dd-productname">01 / FieldOps</p><h2>Out of the office.<br>Into your element.</h2><p>Your maps, terrain and field observations.<br>One capable GIS app for iPhone and iPad.</p><a class="dd-primary" href="{STORE}">Get FieldOps on the App Store ↗</a><a class="dd-text" href="./fieldops.html">Discover FieldOps →</a></div><div class="dd-phones">{img('fieldops-map.png','Actual FieldOps map screenshot','width="1320" height="2868"')}{img('fieldops-terrain.png','Actual FieldOps terrain screenshot','width="1320" height="2868"')}</div></section>
<section class="dd-next"><div><span class="dd-kicker">NEXT UP / COMING SOON</span><h2>Make room for<br>FieldMaps.</h2><p>A new perspective on your spatial data.</p><a class="dd-text" href="./fieldmaps.html">Take a first look ↗</a></div>{img('fieldmaps-web.png','FieldMaps development preview','loading="lazy" width="1280" height="720"')}</section><section class="dd-business"><div class="dd-sectionhead"><span class="dd-kicker">FOR YOUR BUSINESS</span><h2>Bring the operation<br>into focus.</h2></div><div class="dd-businessgrid">{cards}</div></section>'''
 page('index.html','DrillOps · Software for the field', 'FieldOps local GIS, the upcoming FieldMaps, and focused business tools for operations, accounts and projects.',body,home=True)
def build_products():
 for name,(path,tag,title,desc,image) in PRODUCTS.items():
  action='Get FieldOps on the App Store ↗' if name=='FieldOps' else 'Ask about the launch ↗' if name=='FieldMaps' else f'Discuss {name} ↗'
  url=STORE if name=='FieldOps' else f'mailto:admin@drillops.com.au?subject={name}%20enquiry'
  note='Available now for iPhone and iPad' if name=='FieldOps' else 'Development preview. FieldMaps is not yet available.' if name=='FieldMaps' else ''
  signin=f'<a class="dd-text" href="./{APPS[name]}">Already a customer? Sign in to {name} ↗</a>' if name in APPS else ''
  hero=f'''<section class="dd-producthero {'is-field' if name=='FieldOps' else 'is-maps' if name=='FieldMaps' else 'is-business'}"><div class="dd-productcopy"><div class="dd-kicker"><i></i>{tag}</div><p class="dd-productname">DrillOps / {name}</p><h1>{title}</h1><p class="dd-desc">{desc}</p><a class="dd-primary" href="{url}">{action}</a><small>{note}</small>{signin}</div><figure class="dd-productvisual {'portrait' if name=='FieldOps' else ''}"><a href="./assets/products/{image}" target="_blank" rel="noopener" aria-label="View full {name} screenshot">{img(image,name+' actual product screenshot','fetchpriority="high"')}</a><figcaption>{'A first look at the FieldMaps workspace' if name=='FieldMaps' else 'Inside '+name}<span>VIEW FULL SIZE ↗</span></figcaption></figure></section>'''
  detail=(CONTENT/path).read_text()
  related='<section class="dd-related"><h3>Explore the collection</h3>'+''.join(f'<a href="./{p[0]}">{n} ↗</a>' for n,p in PRODUCTS.items() if n!=name)+'</section>'
  page(path,name+' · DrillOps',desc,hero+'<div class="dd-content">'+detail+'</div>'+related,name)
def build_documents():
 for name in ['support','privacy','fieldops-support','fieldops-privacy']:
  body=(CONTENT/(name+'.html')).read_text()
  title=re.sub('<[^>]+>','',re.search(r'<h1[^>]*>(.*?)</h1>',body,re.S).group(1))
  page(name+'.html',title+' · DrillOps',title+' information and help.','<div class="dd-content">'+body+'</div>')
def build():
 build_home();build_products();build_documents()
if __name__=='__main__':build()
